// The Delves: one dungeon under each Far Land. Layouts are generated from a fixed seed, so every player's dungeon is stable.
const rngOf = (seed) => () => { seed = (seed + 0x6D2B79F5) | 0; let x = Math.imul(seed ^ (seed >>> 15), 1 | seed); x ^= x + Math.imul(x ^ (x >>> 7), 61 | x); return ((x ^ (x >>> 14)) >>> 0) / 4294967296; };
const npc = (id, name, x, y, lines, o = {}) => ({ id, cast: null, name, x, y, story: "", lines, ...o });
