const body = (g, h, c, a, now, still) => { const q = still ? 0 : Math.sin(now / 120 + h.x) * 2; g.fillStyle = "rgba(0,0,0,.25)"; g.beginPath(); g.ellipse(h.x, h.y + 13, 13, 5, 0, 0, 7); g.fill(); g.fillStyle = c; g.strokeStyle = a; g.lineWidth = 2; return q; };
const eyes = (g, x, y) => { g.fillStyle = "#ff3a48"; g.fillRect(x - 6, y, 4, 4); g.fillRect(x + 2, y, 4, 4); };
const monsters = (c, a) => ({
  melee: (g, h, now, still) => { const q = body(g, h, c, a, now, still); g.beginPath(); g.ellipse(h.x, h.y - 2 + q / 2, 15, 12, 0, 0, 7); g.fill(); g.stroke(); for (const s of [-1, 1]) { g.beginPath(); g.moveTo(h.x + s * 12, h.y - 4); g.lineTo(h.x + s * 25, h.y - 10 + q); g.lineTo(h.x + s * 15, h.y + 4); g.closePath(); g.fill(); g.stroke(); } eyes(g, h.x, h.y - 6); },
  shoot: (g, h, now, still) => { const q = body(g, h, c, a, now, still); g.beginPath(); g.moveTo(h.x - 14, h.y + 13); g.quadraticCurveTo(h.x - 16, h.y - 24 + q, h.x, h.y - 28 + q); g.quadraticCurveTo(h.x + 16, h.y - 24 + q, h.x + 14, h.y + 13); g.closePath(); g.fill(); g.stroke(); g.fillStyle = a; g.beginPath(); g.arc(h.x, h.y - 2, 6 + (now < (h.fire || 0) - 1200 ? 2 : 0), 0, 7); g.fill(); eyes(g, h.x, h.y - 18 + q); },
  charge: (g, h, now, still) => { const q = body(g, h, c, a, now, still), w = h.cState === "wind" ? 2 : 0; g.fillRect(h.x - 18 - w, h.y - 10, 36 + w * 2, 22); g.strokeRect(h.x - 18 - w, h.y - 10, 36 + w * 2, 22); g.fillStyle = a; g.beginPath(); g.moveTo(h.x - 16, h.y - 10); g.lineTo(h.x - 24, h.y - 24 + q); g.lineTo(h.x - 7, h.y - 10); g.moveTo(h.x + 16, h.y - 10); g.lineTo(h.x + 24, h.y - 24 + q); g.lineTo(h.x + 7, h.y - 10); g.fill(); eyes(g, h.x, h.y - 5); },
});
