function floor(d, idx, f, last, r) {
  const w = 46, h = 32, rooms = [], rects = [], hounds = [], teeth = [], props = [], names = ["melee", "shoot", "charge"]; let guard = 0;
  while (rooms.length < 7 + Math.min(2, f) && guard++ < 400) { const rw = 7 + Math.floor(r() * 6), rh = 5 + Math.floor(r() * 4), x = 2 + Math.floor(r() * (w - rw - 4)), y = 2 + Math.floor(r() * (h - rh - 4)); if (rooms.some((q) => x < q.x + q.w + 2 && x + rw + 2 > q.x && y < q.y + q.h + 2 && y + rh + 2 > q.y)) continue; rooms.push({ x, y, w: rw, h: rh, cx: x + Math.floor(rw / 2), cy: y + Math.floor(rh / 2) }); }
  rooms.sort((a, b) => a.cx - b.cx); for (const q of rooms) rects.push([q.x, q.y, q.w, q.h, d[2]]);
  for (let i = 1; i < rooms.length; i++) { const a = rooms[i - 1], b = rooms[i], top = Math.min(a.cy, b.cy), left = Math.min(a.cx, b.cx); rects.push([left, a.cy, Math.abs(a.cx - b.cx) + 2, 2, d[2]], [b.cx, top, 2, Math.abs(a.cy - b.cy) + 2, d[2]]); if (f > 0 && r() < .5 + f * .1 && Math.abs(a.cx - b.cx) > 7) { const tx = left + 3 + Math.floor(r() * (Math.abs(a.cx - b.cx) - 5)); if (!rooms.some((q) => tx >= q.x - 1 && tx <= q.x + q.w && a.cy >= q.y - 1 && a.cy <= q.y + q.h)) teeth.push([tx, a.cy], [tx, a.cy + 1]); } }
  const start = rooms[0], end = rooms.at(-1); rooms.slice(1).forEach((q, i) => { const n = 1 + Math.floor(r() * 2) + (f > 1 && r() < .4 ? 1 : 0); for (let k = 0; k < n; k++) hounds.push([q.x + 1 + Math.floor(r() * (q.w - 2)), q.y + 1 + Math.floor(r() * (q.h - 2)), names[f === 0 ? (r() < .75 ? 0 : 1) : Math.floor(r() * 3)]]); void i; });
  const seen = new Set(), uniq = hounds.filter((q) => { const k = q[0] + "," + q[1]; if (seen.has(k)) return false; seen.add(k); return true; });
  const id = `f${f}`, doors = [{ x: start.cx - 1, y: start.cy - 1, to: f === 0 ? null : `f${f - 1}`, tx: 0, ty: 0, label: "Back up the stairs" }, { x: end.cx, y: end.cy, to: `f${f + 1}`, tx: 0, ty: 0, label: last ? "Descend to the heart" : "Descend", clear: true, lock: "The stairs are sealed. Clear this floor first." }]; if (f === 0) doors.shift();
  return { id, name: `${d[1]} · Floor ${f + 1}`, room: 1, w, h, base: "wall", bg: "#050508", tint: d[3], r: rects, hounds: uniq, teeth, props, doors, noRespawn: true, power: idx + f * .35, monster: "melee", toothLine: "The floor had teeth. They were right about it.", houndLine: `${d[6][0]} got you. The dark is very pleased with itself.`, start: [start.cx, start.cy], end: [end.cx, end.cy], rooms };
}

export function makeDelves() {
  const out = {}; D.forEach((d, i) => {
    const r = rngOf(4217 + i * 991), scenes = {}, N = 4; for (let f = 0; f < N; f++) scenes[`f${f}`] = floor(d, i, f, f === N - 1, r);
    const arena = { id: "heart", name: `${d[1]} · The Heart`, room: 1, w: 21, h: 15, base: d[2], bg: "#050508", tint: d[3], r: [], props: [], doors: [{ x: 10, y: 14, to: "f3", tx: 0, ty: 0, label: "Back up the stairs" }], noRespawn: true, npcs: [npc("delveboss", d[7], 10, 5, [d[11]], { art: "relic", verb: "Face", boss: "d-" + d[0] })], start: [10, 12], end: [10, 12], power: i + 2 };
    for (let f = 0; f < N; f++) { const s = scenes[`f${f}`]; for (const q of s.doors) { if (q.to === `f${f + 1}` && scenes[q.to]) { const t = scenes[q.to]; q.tx = t.start[0]; q.ty = t.start[1]; } else if (q.to === `f${f - 1}`) { const t = scenes[q.to]; q.tx = t.end[0] - 1; q.ty = t.end[1] + 1; } } } const lastF = scenes.f3, ex = lastF.doors.find((q) => q.clear); ex.to = "heart"; ex.tx = 10; ex.ty = 12; arena.doors[0].tx = lastF.end[0] - 1; arena.doors[0].ty = lastF.end[1] + 1; scenes.heart = arena;
    const relics = []; for (let f = 0; f < N; f++) { const s = scenes[`f${f}`], rm = s.rooms[1 + Math.floor(r() * (s.rooms.length - 2))]; relics.push({ id: `c${f}`, s: `f${f}`, x: rm.x + 1, y: rm.y + 1, name: "a delver's cache", text: ["Coins, a candle stub and a note that says TURN BACK, with a smiley face.", "Somebody's lunch from a very long time ago, and a purse they won't be needing.", "A map of this exact room with an X on it. You are standing on the X. Rude.", "A lockbox that has been waiting for anyone at all."][f], story: "" }); }
    for (const s of Object.values(scenes)) { delete s.rooms; }
    out["delve-" + d[0]] = { title: d[1], delve: true, rpgKind: "delve", series: "kitsune", tier: i, start: ["f0", ...scenes.f0.start], respawn: ["f0", ...scenes.f0.start], building: () => {}, deathWord: "Times carried out", endStory: "", doneGoal: "", monsters: monsters(d[4], d[5]), enemyNames: d[6], meterLine: "You ran out of health.", deathBy: null, deathLine: (n, t) => `${t} A passing delver dragged you back to the first floor by the tail. That's ${n} now.`, intro: `${d[1]}. Clear each floor to unseal the stairs. Watch for spitters, and when something stops and stares at you, move.`, ending: "", scenes, quest: [], relics };
  }); return out;
}

