export function makeBounties(list) { const out = {}; list.forEach((b, n) => { const r = rngOf(9001 + n * 313), th = THEME[b.region] || THEME.village, w = 28, h = 18, spot = () => [3 + Math.floor(r() * (w - 6)), 2 + Math.floor(r() * 8)], pack = (k) => Array.from({ length: k }, () => [...spot(), ["melee", "shoot", "charge"][Math.floor(r() * 3)]]), waves = [pack(2 + Math.ceil(b.lv / 3)), [...pack(2 + Math.ceil(b.lv / 3)), [Math.floor(w / 2), 5, b.lv % 2 ? "charge" : "melee", 3.4]]], scene = { id: "arena", name: b.name, room: 1, w, h, base: th[0], bg: "#050508", tint: "rgba(120,20,30,.07)", r: [], props: [["bench", 2, 15], ["bench", 25, 15]], doors: [], noRespawn: true, power: b.lv * .75, monster: "melee", hounds: pack(1 + Math.ceil(b.lv / 3)), waves, toothLine: "", houndLine: `${b.name} got you.`, start: [14, 15], end: [14, 15] }; out["bounty-" + b.id] = { title: `Bounty: ${b.name}`, delve: true, bountyId: b.id, rpgKind: "delve", series: "kitsune", tier: b.lv, start: ["arena", 14, 15], respawn: ["arena", 14, 15], building: () => {}, deathWord: "Times beaten", endStory: "", doneGoal: "", monsters: monsters(th[1], th[2]), enemyNames: [b.name], meterLine: "You ran out of health.", deathBy: null, deathLine: (k, t) => `${t} You come round at the edge of its territory. It's still there. That's ${k} now.`, intro: `${b.name}. ${b.text} Clear the pack, and it will come for you.`, ending: "", scenes: { arena: scene }, quest: [], relics: [] }; }); return out; }

// The Bottomless Stair: an endless run. Eight floor layouts repeat while the danger keeps climbing.
export const STAIR_MODS = [["", ""], ["Swift", "Enemies move faster"], ["Armoured", "Enemies have 40% more health"], ["Frenzied", "Enemies hit harder"], ["Crowded", "More enemies on this floor"], ["Brittle", "Enemies have 30% less health"], ["Rich", "Bonus mon on floor clear"], ["Biting", "More floor traps"], ["Misty", "Deep-shadow floor"], ["Nimble", "Faster movement & dash"]];
