export function makeStair() { const r = rngOf(31337), scenes = {}, N = 16; for (let i = 0; i < N; i++) { const d = D[i % D.length], s = floor(d, 0, 2, false, r); s.id = "e" + i; s.name = "The Bottomless Stair"; s.doors = [{ x: s.end[0], y: s.end[1], to: "e" + ((i + 1) % N), tx: 0, ty: 0, label: "Descend", clear: true, lock: "The stairs are sealed. Clear this floor first.", descend: true }]; s.power = 0; scenes[s.id] = s; } for (let i = 0; i < N; i++) { const t = scenes["e" + ((i + 1) % N)], q = scenes["e" + i].doors[0]; q.tx = t.start[0]; q.ty = t.start[1]; } for (const s of Object.values(scenes)) delete s.rooms; return { "delve-stair": { title: "The Bottomless Stair", delve: true, endless: true, rpgKind: "delve", series: "kitsune", tier: 0, start: ["e0", ...scenes.e0.start], respawn: ["e0", ...scenes.e0.start], building: () => {}, deathWord: "Runs ended", endStory: "", doneGoal: "", monsters: monsters("#8a7ac8", "#2c2460"), enemyNames: ["Stair Thing"], meterLine: "You ran out of health.", deathBy: null, deathLine: (n, t) => t, intro: "The Bottomless Stair. It goes down for as long as you do. Pick a boon after each floor. When you fall or leave, you keep what you've earned and the stair starts over.", ending: "", scenes, quest: [], relics: [] } }; }
